# Surah Al-Kahf (chapter 18) — part 2: ayat 11-20 (IDs 2151-2160)
SURAH = 18

ENTRIES = {
2151: (
"پس ہم نے ان کے کانوں پر غار میں گنتی کے سالوں کے لیے مہر لگا دی",
"""۱۔ اصحابِ کہف کو اللہ نے طویل نیند دی — کئی سو سال؛ اللہ کی قدرت کی نشانی۔
۲۔ ’’فَضَرَبْنَا عَلَىٰ آذَانِهِمْ فِي الْكَهْفِ سِنِينَ عَدَدًا‘‘ — پس ہم نے ان کے کانوں پر غار میں گنتی کے سالوں کے لیے مہر لگا دی — یعنی ہم نے ان کے کانوں پر مہر لگا دی اور وہ غار میں کئی سال سوئے رہے۔
۳۔ عملی سبق: اللہ کی قدرت بے پناہ ہے؛ اس کے فیصلے پر یقین رکھیں۔"""
),
2152: (
"پھر ہم نے انہیں بیدار کیا تاکہ ہم دیکھیں کہ دونوں فریقوں میں سے کون اس بات کی گنتی بہتر کر سکتا ہے کہ وہ کتنا مدت رہے",
"""۱۔ اللہ نے اصحابِ کہف کو جگایا؛ لوگوں نے ان کی نیند کی مدت کے بارے میں بحث کی۔
۲۔ ’’ثُمَّ بَعَثْنَاهُمْ لِنَعْلَمَ أَيُّ الْحِزْبَيْنِ أَحْصَىٰ لِمَا لَبِثُوا أَمَدًا‘‘ — پھر ہم نے انہیں بیدار کیا تاکہ ہم دیکھیں کہ دونوں فریقوں میں سے کون اس بات کی گنتی بہتر کر سکتا ہے کہ وہ کتنا مدت رہے — یعنی پھر ہم نے انہیں اٹھایا تاکہ دیکھیں کہ کس فریق نے مدتِ قیام کا بہتر حساب لگایا۔
۳۔ عملی سبق: اللہ ہی سب کچھ جانتا ہے؛ گمانوں پر یقین نہ کرو۔"""
),
2153: (
"ہم آپ کو ان کی پوری خبر حق کے ساتھ بیان کر رہے ہیں — بے شک وہ کچھ جوان تھے جو اپنے رب پر ایمان لائے — اور ہم نے ان کی ہدایت میں اضافہ کیا",
"""۱۔ اللہ نے اصحابِ کہف کا اصل واقعہ بیان کیا؛ جوان مؤمن؛ اللہ نے ان کی ہدایت بڑھائی۔
۲۔ ’’نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِالْحَقِّ إِنَّهُمْ فِتْيَۃٌ آمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًى‘‘ — ہم آپ کو ان کی پوری خبر حق کے ساتھ بیان کر رہے ہیں — بے شک وہ کچھ جوان تھے جو اپنے رب پر ایمان لائے — اور ہم نے ان کی ہدایت میں اضافہ کیا — یعنی ہم آپ کو ان کا واقعہ حق کے ساتھ سناتے ہیں — وہ کچھ جوان تھے جو اپنے رب پر ایمان لائے اور ہم نے ان کی ہدایت بڑھا دی۔
۳۔ عملی سبق: ایمان پر ثابت قدم رہو؛ اللہ ہدایت میں اضافہ کرتا ہے۔"""
),
2154: (
"اور ہم نے ان کے دلوں کو مضبوط کیا جب وہ کھڑے ہوئے اور کہا کہ ہمارا رب آسمانوں اور زمین کا رب ہے — ہم اس کے سوا کسی معبود کو نہیں پکاریں گے — اگر ہم نے ایسا کہا تو ہم نے حقیقت میں بہت بڑی بے ہودہ بات کہی",
"""۱۔ اصحابِ کہف نے ثابت قدم رہ کر توحید کا اعلان کیا؛ شرک سے اعلانِ برات۔
۲۔ ’’وَرَبَطْنَا عَلَىٰ قُلُوبِهِمْ إِذْ قَامُوا فَقَالُوا رَبُّنَا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ لَن نَّدْعُوَ مِن دُونِهِ إِلَٰهًا لَّقَدْ قُلْنَا إِذًا شَطَطًا‘‘ — اور ہم نے ان کے دلوں کو مضبوط کیا جب وہ کھڑے ہوئے اور کہا کہ ہمارا رب آسمانوں اور زمین کا رب ہے — ہم اس کے سوا کسی معبود کو نہیں پکاریں گے — اگر ہم نے ایسا کہا تو ہم نے حقیقت میں بہت بڑی بے ہودہ بات کہی — یعنی ہم نے ان کے دلوں کو مضبوط کر دیا جب وہ کھڑے ہوئے پس انہوں نے کہا ہمارا رب آسمانوں اور زمین کا رب ہے — ہم اس کے سوا کوئی معبود نہیں پکاریں گے — اگر ایسا کیا تو ہم یقیناً بے ہودہ بات کہنے والے ہوں گے۔
۳۔ عملی سبق: توحید پر ثابت قدم رہو؛ اللہ کی پناہ مانگو۔"""
),
2155: (
"یہ ہمارے لوگ ہیں جنہوں نے اس کے سوا دوسرے معبود بنا لیے — کاش یہ ان پر واضح دلیل لے آتے — پس اس سے بڑھ کر ظالم کون ہے جو اللہ پر جھوٹ گھڑے",
"""۱۔ مشرکین بغیر دلیل کے معبود بناتے ہیں؛ سب سے بڑا ظالم اللہ پر جھوٹ گھڑنے والا ہے۔
۲۔ ’’هَٰؤُلَاءِ قَوْمُنَا اتَّخَذُوا مِن دُونِهِ آلِهَۃً لَّوْلَا يَأْتُونَ عَلَيْهِم بِسُلْطَانٍ بَيِّنٍ فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا‘‘ — یہ ہمارے لوگ ہیں جنہوں نے اس کے سوا دوسرے معبود بنا لیے — کاش یہ ان پر واضح دلیل لے آتے — پس اس سے بڑھ کر ظالم کون ہے جو اللہ پر جھوٹ گھڑے — یعنی یہ ہمارے قوم والے ہیں جنہوں نے اس کے سوا معبود بنا لیے — کاش وہ ان پر واضح دلیل لے آتے — پس اس سے بڑا ظالم کون ہے جو اللہ پر جھوٹ گھڑے۔
۳۔ عملی سبق: بغیر دلیل کے ایسی بات نہ کہیں؛ اللہ پر جھوٹ گھڑنا بڑی برائی ہے۔"""
),
2156: (
"اور جب تم ان سے اور ان کی معبودوں سے الگ ہو جاؤ سوائے اللہ کے تو غار میں پناہ لے لو — آپ کا رب تم پر اپنی رحمت پھیلا دے گا اور تمہارے معاملے میں سہولت پیدا کرے گا",
"""۱۔ مشرکوں سے الگ ہو کر اللہ کی پناہ مانگو؛ وہ رحمت اور سہولت دیتا ہے۔
۲۔ ’’وَإِذِ اعْتَزَلْتُمُوهُمْ وَمَا يَعْبُدُونَ إِلَّا اللَّهَ فَأْوُوا إِلَى الْكَهْفِ يَنشُرْ لَكُمْ رَبُّكُم مِّن رَّحْمَتِهِ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًا‘‘ — اور جب تم ان سے اور ان کی معبودوں سے الگ ہو جاؤ سوائے اللہ کے تو غار میں پناہ لے لو — آپ کا رب تم پر اپنی رحمت پھیلا دے گا اور تمہارے معاملے میں سہولت پیدا کرے گا — یعنی جب تم ان لوگوں اور ان کی معبودوں سے جدا ہو جاؤ سوائے اللہ کے تو غار میں پناہ لے لو — تمہارا رب تم پر اپنی رحمت پھیلائے گا اور تمہارے معاملے میں سہولت پیدا کرے گا۔
۳۔ عملی سبق: شرک سے الگ ہو کر صرف اللہ کی پناہ لو؛ وہ رحمت دیتا ہے۔"""
),
2157: (
"اور آپ دیکھیں گے کہ سورج جب طلوع ہوتا ہے تو ان کے غار سے دائیں طرف ہٹ جاتا ہے — اور جب غروب ہوتا ہے تو ان سے بائیں طرف کٹ کر گزر جاتی ہے — اور وہ غار کے کھلے حصے میں ہیں — یہ اللہ کی نشانیوں میں سے ہے — جسے اللہ ہدایت دے وہ ہدایت یافتہ ہے اور جسے وہ گمراہ کرے تو آپ اس کے لیے کوئی مددگار مرشد نہیں پائیں گے",
"""۱۔ اللہ نے اصحابِ کہف کو دھوپ سے بچا کر محفوظ رکھا؛ یہ اللہ کی نشانی تھی؛ ہدایت اللہ ہی دیتا ہے۔
۲۔ ’’وَتَرَى الشَّمْسَ إِذَا طَلَعَت تَّزَاوَرُ عَن كَهْفِهِمْ ذَاتَ الْيَمِينِ وَإِذَا غَرَبَت تَّقْرِضُهُمْ ذَاتَ الشِّمَالِ وَهُمْ فِي فَجْوَۃٍ مِّنْهُ ذَٰلِكَ مِنْ آيَاتِ اللَّهِ مَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُ وَلِيًّا مُّرْشِدًا‘‘ — اور آپ دیکھیں گے کہ سورج جب طلوع ہوتا ہے تو ان کے غار سے دائیں طرف ہٹ جاتا ہے — اور جب غروب ہوتا ہے تو ان سے بائیں طرف کٹ کر گزر جاتی ہے — اور وہ غار کے کھلے حصے میں ہیں — یہ اللہ کی نشانیوں میں سے ہے — جسے اللہ ہدایت دے وہ ہدایت یافتہ ہے اور جسے وہ گمراہ کرے تو آپ اس کے لیے کوئی مددگار مرشد نہیں پائیں گے — یعنی آپ دیکھیں گے کہ سورج جب طلوع ہوتا ہے تو ان کے غار سے دائیں طرف ہٹ جاتا ہے اور غروب ہوتا ہے تو بائیں طرف کٹ کر گزر جاتی ہے — وہ غار کے کھلے حصے میں محفوظ ہیں — یہ اللہ کی نشانیوں میں سے ہے — جسے اللہ ہدایت دے وہ ہدایت یافتہ ہے اور جسے وہ گمراہ کرے تو آپ اس کے لیے کوئی رہنما مددگار نہیں پائیں گے۔
۳۔ عملی سبق: اللہ کی نشانیوں پر یقین رکھیں؛ ہدایت اللہ کے سوا کوئی نہیں دے سکتا۔"""
),
2158: (
"اور آپ انہیں بیدار سمجھتے ہیں جبکہ وہ سوئے ہوئے ہیں — اور ہم انہیں دائیں اور بائیں طرف لٹاتے ہیں — اور ان کا کتا دروازے پر اپنی دونوں بازویں پھیلائے ہوئے ہے — اگر آپ ان پر نظر ڈالیں تو ان سے بھاگ جائیں اور ان سے خوف سے بھر جائیں",
"""۱۔ اصحابِ کہف کی حالت — سوتے مگر سو نہ محسوس ہوں؛ کتا دروازہ پر حفاظت؛ اللہ کی حفاظت۔
۲۔ ’’وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ وَنُقَلِّبُهُمْ ذَاتَ الْيَمِينِ وَذَاتَ الشِّمَالِ وَكَلْبُهُم بَاسِطٌ ذِرَاعَيْهِ بِالْوَصِيدِ لَوِ اطَّلَعْتَ عَلَيْهِمْ لَوَلَّيْتَ مِنْهُمْ فِرَارًا وَلَمُلِئْتَ مِنْهُمْ رُعْبًا‘‘ — اور آپ انہیں بیدار سمجھتے ہیں جبکہ وہ سوئے ہوئے ہیں — اور ہم انہیں دائیں اور بائیں طرف لٹاتے ہیں — اور ان کا کتا دروازے پر اپنی دونوں بازویں پھیلائے ہوئے ہے — اگر آپ ان پر نظر ڈالیں تو ان سے بھاگ جائیں اور ان سے خوف سے بھر جائیں — یعنی آپ انہیں جاگتے ہوئے سمجھتے ہیں جبکہ وہ سوئے ہوئے ہیں — ہم انہیں دائیں بائیں پلٹتے ہیں — ان کا کتا دروازے پر بازو پھیلائے سویا ہوا ہے — اگر آپ ان پر نظر ڈالیں تو بھاگ جائیں اور خوف سے بھر جائیں۔
۳۔ عملی سبق: اللہ کی حفاظت پر بھروسہ کرو؛ بندگانِ خدا کے ساتھ نرم رہو۔"""
),
2159: (
"اور اسی طرح ہم نے انہیں بیدار کیا تاکہ وہ آپس میں پوچھ گچھ کریں — ایک نے ان میں سے پوچھا تم کتنی مدت رہے؟ کہا ہم ایک دن یا دن کا کچھ حصہ رہے — کہا تمہارا رب بہتر جانتا ہے کہ تم کتنی مدت رہے — پس اپنے میں سے ایک کو اپنے پاس سے یہ چاندی لے کر شہر بھیجو اور دیکھو کون سا کھانا بہتر ہے تو اس میں سے لے آؤ اور ہوشیار رہو اور کسی کو اپنا پتا نہ دینا",
"""۱۔ اصحابِ کہف کی بحث — مدتِ قیام کا علم اللہ کو ہے؛ انہوں نے انجان کھانا منگوایا۔
۲۔ ’’وَكَذَٰلِكَ بَعَثْنَاهُمْ لِيَتَسَاءَلُوا بَيْنَهُمْ قَالَ قَائِلٌ مِّنْهُمْ كَمْ لَبِثْتُمْ قَالُوا لَبِثْنَا يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالُوا رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ فَابْعَثُوا أَحَدَكُم بِوَرِقِكُمْ هَٰذِهِ إِلَى الْمَدِينَۃِ فَلْيَنظُرْ أَيُّهَا أَزْكَىٰ طَعَامًا فَلْيَأْتِكُم بِرِزْقٍ مِّنْهُ وَلْيَتَلَطَّفْ وَلَا يُشْعِرَنَّ بِكُمْ أَحَدًا‘‘ — اور اسی طرح ہم نے انہیں بیدار کیا تاکہ وہ آپس میں پوچھ گچھ کریں — ایک نے ان میں سے پوچھا تم کتنی مدت رہے؟ کہا ہم ایک دن یا دن کا کچھ حصہ رہے — کہا تمہارا رب بہتر جانتا ہے کہ تم کتنی مدت رہے — پس اپنے میں سے ایک کو اپنے پاس سے یہ چاندی لے کر شہر بھیجو اور دیکھو کون سا کھانا بہتر ہے تو اس میں سے لے آؤ اور ہوشیار رہو اور کسی کو اپنا پتا نہ دینا — یعنی اسی طرح ہم نے انہیں اٹھایا تاکہ وہ آپس میں ایک دوسرے سے پوچھیں — ایک نے کہا تم کتنی مدت رہے؟ انہوں نے کہا ایک دن یا دن کا کچھ حصہ — کہا تمہارا رب جانتا ہے تم کتنی مدت رہے — پس اپنے ساتھیوں میں سے ایک کو پیسوں کے ساتھ شہر بھیجو اور دیکھو کون سا کھانا بہتر ہے اور اس میں سے کھانا لائیں اور ہوشیار رہنا اور کسی کو اپنا پتا نہ دینا۔
۳۔ عملی سبق: اللہ کا علم بے پناہ ہے؛ اپنے حالات خود نہ گھبرائیں؛ اللہ کافی ہے۔"""
),
2160: (
"بے شک اگر وہ تم پر قابو پا گئے تو تمہیں سنگسار کر دیں گے یا تمہیں اپنے دین میں واپس لے جائیں گے اور اس وقت تم ہرگز کامیاب نہ ہو",
"""۱۔ اصحابِ کہف کی احتیاط — مشرکین کی سخت کوئی رحم نہیں؛ مومنوں کو اپنی حفاظت کرنی چاہیے۔
۲۔ ’’إِنَّهُمْ إِن يَظْهَرُوا عَلَيْكُمْ يَرْجُمُوكُمْ أَوْ يُعِيدُوكُمْ فِي مِلَّتِهِمْ وَلَن تُفْلِحُوا إِذًا أَبَدًا‘‘ — بے شک اگر وہ تم پر قابو پا گئے تو تمہیں سنگسار کر دیں گے یا تمہیں اپنے دین میں واپس لے جائیں گے اور اس وقت تم ہرگز کامیاب نہ ہو — یعنی اگر وہ تمہیں پکڑ لیں تو تمہیں سنگسار کر دیں گے یا اپنے دین میں واپس کر لیں گے اور پھر تم ہرگز کامیاب نہ ہو گے۔
۳۔ عملی سبق: ایمان کی حفاظت کرو؛ مشرکین کی طاقت سے بچو؛ اللہ کا مددگار رہو۔"""
),
}
